/** The broker's app-bound fragment: a token to exchange, or the provider error it forwarded. */
export type ManagedFragment =
  | { nonce: string; token: string }
  | { nonce: string; error: string; errorDescription?: string };

/**
 * Parses the broker's `#token=…&nonce=…` / `#error=…` fragment from a full callback URL or a
 * `location.hash` value. Manual `#` split — WHATWG URL parsing of custom-scheme deep links
 * (`exp://`, `myapp://`) is unreliable across runtimes, and Hermes is one of them.
 */
// The ManagedFragment return type is load-bearing: it is the discriminated union `"error" in
// fragment` narrows on — inference would produce optional-property shapes that don't narrow.
export const parseFragment = (input: string): ManagedFragment | undefined => {
  const hashIndex = input.indexOf("#");
  if (hashIndex === -1) return undefined;
  const params = new URLSearchParams(input.slice(hashIndex + 1));
  const nonce = params.get("nonce");
  const token = params.get("token");
  const error = params.get("error");
  if (!nonce) return undefined;
  if (token) return { nonce, token };
  if (error)
    return { nonce, error, errorDescription: params.get("error_description") ?? undefined };
  return undefined;
};

/** Maps a provider-error fragment forwarded by the broker to the shared sign-in error shape. */
export const providerErrorResult = (fragment: Extract<ManagedFragment, { error: string }>) => ({
  data: null,
  error: { code: fragment.error, message: fragment.errorDescription ?? fragment.error },
});
